package hu.synostream.android;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class TorrentPagingTest {
 static final class Pages implements DownloadStation.Transport {int count=235,cap=100,calls;boolean pageTotal,missingTotal,repeat,truncated;public JSONObject call(String api,String method,boolean readonly,JSONObject p,String name,byte[] bytes)throws Exception{assertTrue(readonly);assertEquals("list",method);assertEquals(DownloadStation.TASK,api);calls++;int offset=repeat?0:p.getInt("offset"),end=Math.min(count,offset+Math.min(cap,p.getInt("limit")));JSONArray rows=new JSONArray();if(!truncated||offset==0)for(int i=offset;i<end;i++)rows.put(new JSONObject().put("id","task-"+i).put("title","Task "+i).put("status",i==count-1?"downloading":"seeding"));JSONObject result=new JSONObject().put("tasks",rows);if(!missingTotal)result.put("total",pageTotal?rows.length():count);return result;}}
 DownloadStation model(Pages p){return new DownloadStation(p,new TorrentRulesTest.Memory(),"fixture");}
 @Test public void pageCountDoesNotTruncateAtOneHundred()throws Exception{Pages p=new Pages();p.pageTotal=true;List<JSONObject> rows=model(p).tasks();assertEquals(235,rows.size());assertEquals("downloading",rows.get(234).getString("status"));assertEquals(4,p.calls);}
 @Test public void absentTotalStillReadsAllPages()throws Exception{Pages p=new Pages();p.missingTotal=true;assertEquals(235,model(p).tasks().size());}
 @Test public void serverSideSmallerPageCapIsSupported()throws Exception{Pages p=new Pages();p.cap=25;p.pageTotal=true;assertEquals(235,model(p).tasks().size());assertEquals(11,p.calls);}
 @Test public void globalTotalAndExactPageBoundaryAreSupported()throws Exception{Pages p=new Pages();p.count=200;assertEquals(200,model(p).tasks().size());assertEquals(3,p.calls);}
 @Test public void emptyQueueCompletesInOneRequest()throws Exception{Pages p=new Pages();p.count=0;assertTrue(model(p).tasks().isEmpty());assertEquals(1,p.calls);}
 @Test public void ignoredOffsetDoesNotLoopOrReturnDuplicates()throws Exception{Pages p=new Pages();p.repeat=true;assertThrows(IOException.class,()->model(p).tasks());assertEquals(2,p.calls);}
 @Test public void advertisedMissingRecordsAreAnError()throws Exception{Pages p=new Pages();p.truncated=true;assertThrows(IOException.class,()->model(p).tasks());}
 @Test public void activeNewestTaskLeadsDefaultViewWithoutBreakingColumnSorting()throws Exception{JSONObject old=new JSONObject().put("id","old").put("title","A").put("status","seeding"),recent=new JSONObject().put("id","new").put("title","Z").put("status","downloading").put("additional",new JSONObject().put("detail",new JSONObject().put("create_time","100")));List<JSONObject> input=List.of(old,recent);assertSame(recent,DownloadsUi.ordered(input,"recent",false).get(0));assertSame(old,DownloadsUi.ordered(input,"title",false).get(0));assertSame(recent,DownloadsUi.ordered(input,"title",true).get(0));assertSame(old,input.get(0));}
}
